  if (code === "000" || result === "SUCCESS") return "CONFIRMED";
  if (code === "111" || code === "927" || code === "999" || ["INPROGRESS", "PENDING", "AMBIGOUS", "AMBIGUOUS"].includes(result)) return null;
  return "FAILED";
}

